package com.ganesh.bookshop.controller; import com.ganesh.bookshop.model.Book; import com.ganesh.bookshop.service.BookService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/api/books") @CrossOrigin(origins="*") public class BookController {private final BookService s; public BookController(BookService s){this.s=s;} @GetMapping public List<Book> all(@RequestParam(required=false)String search){return s.all(search);} @GetMapping("/{id}") public Book one(@PathVariable Long id){return s.one(id);} @PostMapping public ResponseEntity<Book> create(@Valid @RequestBody Book b){return ResponseEntity.status(201).body(s.save(b));} @PutMapping("/{id}") public Book update(@PathVariable Long id,@Valid @RequestBody Book b){return s.update(id,b);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}